"""Public-facing editorial compositions for Ilyass Chakir's portfolio."""

def venture_brief():
    return '''<section class="venture-outcomes wrap" id="vision"><div class="section-heading"><div><p class="eyebrow">ENTREPRENEURIAL VISION</p><h2>Built in Morocco.<br><em>With Morocco in mind.</em></h2></div><p>Intended benefits guide the product.<br>They are goals to validate, not impact already claimed.</p></div><div class="outcome-grid"><article><h3>More informed visitors</h3><p>Help travelers discover places through geographic context, reviewed practical information and explanations they can understand.</p></article><article><h3>A place for local value</h3><p>Aim to give relevant local places and cultural experiences a clearer presence, with accurate identity and source attribution.</p></article><article><h3>Cultural care</h3><p>Keep the meaning, origin and uncertainty of cultural information visible, rather than presenting generic generated travel advice as fact.</p></article></div><p class="venture-boundary">Marrakech is the initial scope. Wider Moroccan coverage is an ambition that depends on evidence, local review and a reliable operating model.</p></section>'''

def homepage(mark,skills,contact):
    hero='''<section class="hero wrap"><div class="hero-top"><p class="eyebrow">ENGINEERING / DATA / ENTREPRENEURSHIP</p><p class="availability">PFE INTERNSHIP<br>FROM FEBRUARY 2027</p></div><h1>Ilyass Chakir<span class="hero-role">Data Engineering <span>&</span> Applied AI</span></h1><div class="hero-bottom"><p>I design data systems and applied AI around real problems.<br class="desktop-only"> I’m also building ANSUF, an entrepreneurial tourism project for Morocco.</p><div class="hero-actions"><a class="button dark" href="/projects/ansuf/">Discover ANSUF</a><a class="study-link" href="/projects/">Explore all projects</a></div></div><div class="hero-baseline"><span>Fifth-year engineering student · EMSI</span><span>Marrakech, Morocco</span></div></section>'''
    spotlight=f'''<section class="venture-spotlight wrap" aria-labelledby="venture-title"><div class="venture-copy"><p class="eyebrow">LEAD PROJECT · ENTREPRENEURIAL INITIATIVE</p><h2 id="venture-title">ANSUF<span>Technology for a more<br><em>meaningful discovery of Morocco.</em></span></h2><p>My independent tourism technology project brings together geographic discovery, sourced cultural knowledge and intelligent assistance. The ambition is to make exploring Morocco more informed and to help local places be understood in their own context.</p><a class="button venture-button" href="/projects/ansuf/">Explore the vision & engineering</a><dl class="venture-facts"><div><dt>STARTING POINT</dt><dd>Marrakech</dd></div><div><dt>MY ROLE</dt><dd>Product & engineering</dd></div><div><dt>STAGE</dt><dd>Private preview</dd></div></dl></div><div class="venture-diagram">{mark('ansuf')}<p>Geography · Cultural knowledge · Grounded assistance</p><span>Conceptual system illustration</span></div></section>'''
    works=''
    rows=[('nerve','NERVE','STREAMING & OBSERVABILITY','A network event is only the start. NERVE follows it through Kafka, Spark and Iceberg to an incident, its timeline and the measurements behind the finding.','Kafka / Spark / Iceberg / FastAPI'),('aqua-sentinel','AQUA NEXUS (formerly AQUA Sentinel)','SIMULATION & APPLIED ML','A hydraulic simulation and detection platform that examines the relationship between sensor placement, model behavior, false alerts and detection delay.','Python / WNTR / scikit-learn'),('money-trail','Money Trail','FINANCIAL DATA ENGINEERING','Invoice reconciliation and financial control with source provenance, dbt transformations, controlled publication and a documented human review process.','PostgreSQL / dbt / Odoo / Python')]
    results={
        'nerve':('200 events recovered after a Spark interruption','Controlled checkpoint-recovery test; 200 Bronze positions and 200 unique Silver IDs.','engineering-6'),
        'aqua-sentinel':('32/32 simulated leaks detected and localized within five minutes','Physical-balance detector; 64 scenarios and 13 virtual sensors. No field validation.','engineering-5'),
        'money-trail':('18 invoice results published from a local Odoo 18 run','Owner-reported development run; zero bank settlement results.','engineering-6')
    }
    for slug,title,discipline,body,stack in rows:
        headline,scope,anchor=results[slug]
        heading='AQUA NEXUS <span class="former-name">(formerly AQUA Sentinel)</span>' if slug=='aqua-sentinel' else title
        works+=f'''<article class="feature feature-{slug}"><a class="feature-art" href="/projects/{slug}/" aria-label="Read the {title} engineering study">{mark(slug)}<span class="art-caption">{'SIMULATED NETWORK' if slug=='aqua-sentinel' else 'SYSTEM ARCHITECTURE'}</span></a><div class="feature-copy"><p class="eyebrow">{discipline}</p><h3><a href="/projects/{slug}/">{heading}</a></h3><p>{body}</p><div class="project-result"><strong>{headline}</strong><p>{scope}</p><a href="/projects/{slug}/#{anchor}">See validation scope</a></div><p class="stack-line">{stack}</p><a class="study-link" href="/projects/{slug}/">Read the engineering study</a></div></article>'''
    return hero+spotlight+f'''<section class="selected wrap" id="selected-work"><div class="section-heading"><div><p class="eyebrow">SELECTED ENGINEERING WORK</p><h2>Systems with<br><em>something to prove.</em></h2></div><p>Architecture, implementation and evidence.<br>Explore the decisions behind the result.</p></div><div class="features">{works}</div><div class="index-cta"><p>Every project has its own technical study.</p><a class="button outline" href="/projects/">View the complete project index <span>13 PROJECTS</span></a></div></section><section class="capabilities wrap"><div class="section-heading"><div><p class="eyebrow">ENGINEERING CAPABILITIES</p><h2>Skills in <em>context.</em></h2></div><p>Connected to implemented systems<br>and inspectable source evidence.</p></div>{skills()}</section><section class="experience-strip wrap"><p class="eyebrow">PROFESSIONAL EXPERIENCE</p><div><h2>Business requirements.<br><em>Practical implementation.</em></h2><p>At B Tel Bureautique, I collaborate on Odoo integration, data migration and validation, including on-site work in Casablanca and Marrakech.</p><a class="study-link" href="/experience/">Explore my professional experience</a></div></section>'''+contact()
